"""SHIP 78: static/config analysis of Wesolowski/Pietrzak-style VDF setups."""
from __future__ import annotations
import re
from ._cat3_common import find_values, first, has, rx, run_cat3
from .base import Cost, Ctx, Plugin, PluginResult, Target


def analyze(text, objs):
    out = []
    if first(objs, "modulus_generator_knows_factorization", "trapdoor_known") is True or has(text, "knows the factorization", "knows factorization of the modulus", "generator knows the order"):
        out.append(("vdf_trusted_setup_trapdoor",
                    "The VDF modulus/group was generated by a party who knows its factorization/order; that party can compute the delay instantly",
                    "high", "Use a trustless group (class group of imaginary quadratic order) or a multi-party generated RSA modulus with attested destruction."))
    if first(objs, "fiat_shamir_bound", "challenge_bound") is False or has(text, "challenge independent of the input", "challenge_independent_of_input"):
        out.append(("vdf_challenge_not_bound",
                    "The VDF challenge is not Fiat-Shamir-bound to the input; proofs can be precomputed or transplanted",
                    "high", "Derive the challenge as a hash of the VDF input and statement."))
    if first(objs, "verification_performed", "verify_before_open") is False or has(text, "verification skipped", "opens without verification", "skip verification"):
        out.append(("vdf_output_not_verified",
                    "The timelock opens without verifying the VDF output/proof",
                    "high", "Verify the VDF proof before releasing the timelocked value."))
    if first(objs, "checkpoint_skips_work") is True or has(text, "checkpoint allows skipping", "checkpoint_skips_sequential"):
        out.append(("vdf_checkpoint_skip",
                    "Checkpointing lets a parallel prover skip the sequential squaring work, defeating the delay",
                    "medium", "Design checkpoints so resumed work still requires the full sequential squarings."))
    return out[:8]


class VdfTimelockValidator(Plugin):
    id = "vdf_timelock_validator"
    label = "VDF Timelock Validator"
    accepts = []
    passive = True
    cost = Cost.FREE
    group = "web3"
    description = "Evaluates supplied VDF (verifiable delay function) implementations/configs: trusted-setup trapdoors, Fiat-Shamir challenge binding, verification before opening, and sequential-work checkpoints. Not governance timelocks."

    async def run(self, target: Target, ctx: Ctx) -> PluginResult:
        return await run_cat3(self, analyze, target, ctx)
